import path from "node:path";

/** Raw downloads land here. Gitignored; regenerated by `npm run pipeline`. */
export const CACHE_DIR = path.resolve(import.meta.dirname, "cache");

/**
 * Cleaned intermediate tables: one tidy CSV per source, on the source's own
 * geography, before anything is joined. Gitignored and reproducible from the
 * cache. Splitting raw from clean means a join bug never needs a re-download.
 */
export const CLEAN_DIR = path.resolve(import.meta.dirname, "clean");

/** Committed pipeline outputs the app and the MCP server read at runtime. */
export const DATA_DIR = path.resolve(import.meta.dirname, "..", "data");

/**
 * The current ACS 5-year vintage, and a prior one far enough back that the two
 * samples do not overlap — the Census Bureau's own condition for comparing
 * 5-year estimates. 2020-2024 against 2015-2019 satisfies it.
 */
export const ACS_VINTAGE = 2024;
export const ACS_PRIOR_VINTAGE = 2019;

/** 2020 census tract boundaries, the vintage the 2027 designation round uses. */
export const BOUNDARY_VINTAGE = 2020;

/**
 * Jurisdictions that nominate tracts.
 *
 * IRC 1400Z-1(c)(3) with 7701(a)(10) makes "State" mean every state, the
 * District of Columbia, and every U.S. territory — 56 jurisdictions, each
 * nominating through its chief executive under the same 25 percent cap. So the
 * island areas are in scope for the statute even though the ACS does not cover
 * them, and the pipeline has to reach them through a second source rather than
 * dropping them.
 *
 * `source` records which one:
 *  - `acs`   the 2020-2024 ACS 5-year estimates. 50 states, DC, Puerto Rico.
 *  - `decia` the 2020 Census of Island Areas Demographic and Housing
 *            Characteristics file, which is what Treasury used for American
 *            Samoa, Guam, the Northern Marianas and the U.S. Virgin Islands.
 */
export interface State {
  fips: string;
  usps: string;
  name: string;
  source: "acs" | "decia";
}

