/**
 * The four island areas the ACS does not survey. They still nominate tracts
 * under the same statute, so their eligibility comes from the 2020 Census of
 * Island Areas Demographic and Housing Characteristics file instead. Keeping
 * them in a separate list makes the different provenance impossible to overlook,
 * and the manifest reports the vintage mismatch rather than implying that every
 * tract in the country was measured the same way.
 */
export const ISLAND_AREAS: readonly State[] = [
  { fips: "60", usps: "AS", name: "American Samoa", source: "decia" },
  { fips: "66", usps: "GU", name: "Guam", source: "decia" },
  { fips: "69", usps: "MP", name: "Northern Mariana Islands", source: "decia" },
  { fips: "78", usps: "VI", name: "U.S. Virgin Islands", source: "decia" },
];

/** All 56 nominating jurisdictions, whatever their data source. */
export const JURISDICTIONS: readonly State[] = [...STATES, ...ISLAND_AREAS];

export function stateByFips(fips: string): State | undefined {
  return JURISDICTIONS.find((s) => s.fips === fips);
}

/**
 * The Census API accepts at most 50 fields per `get=`, and NAME plus the
 * geography columns count against that. Batching at 24 leaves comfortable
 * headroom and keeps one state's response near 2 MB.
 */
export const VARS_PER_REQUEST = 24;

/** How many state requests to run at once. The API tolerates this; be polite. */
export const FETCH_CONCURRENCY = 6;
